@page "/"

<PageTitle>ShipmentTracker — Home</PageTitle>

<div class="container py-4">
    <div class="text-center mb-5">
        <h1 class="display-5 fw-bold">📦 Shipment Tracker</h1>
        <p class="lead text-muted">Track your shipment in real time. Enter your tracking number below.</p>
    </div>

    <div class="row justify-content-center">
        <div class="col-md-8 col-lg-6">
            <div class="card shadow-sm">
                <div class="card-body p-4">
                    <h5 class="card-title mb-3">Track a Shipment</h5>
                    <div class="input-group">
                        <input type="text" class="form-control" placeholder="e.g. SHP-001-2026"
                               @bind="trackingInput" @bind:event="oninput"
                               @onkeydown="HandleKeyDown" />
                        <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                            @if (isLoading)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Track
                        </button>
                    </div>

                    @if (notFound)
                    {
                        <div class="alert alert-warning mt-3 mb-0">
                            No shipment found for "<strong>@searchedTracking</strong>". Please check the tracking number.
                        </div>
                    }

                    @if (shipment is not null)
                    {
                        <div class="mt-4">
                            <h6>Shipment @shipment.TrackingNumber</h6>
                            <table class="table table-sm">
                                <tbody>
                                    <tr><th>Status</th><td><ShipmentStatusBadge Status="shipment.Status" /></td></tr>
                                    <tr><th>From</th><td>@shipment.Origin</td></tr>
                                    <tr><th>To</th><td>@shipment.Destination</td></tr>
                                    <tr><th>Recipient</th><td>@shipment.RecipientName</td></tr>
                                    <tr><th>Shipped</th><td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td></tr>
                                    <tr>
                                        <th>Est. Delivery</th>
                                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                                    </tr>
                                    @if (shipment.ActualDelivery.HasValue)
                                    {
                                        <tr>
                                            <th>Delivered</th>
                                            <td>@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</td>
                                        </tr>
                                    }
                                    <tr><th>Description</th><td>@shipment.Description</td></tr>
                                </tbody>
                            </table>
                        </div>
                    }
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingInput = string.Empty;
    private string searchedTracking = string.Empty;
    private ShipmentDto? shipment;
    private bool notFound;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        var query = trackingInput.Trim();
        if (string.IsNullOrEmpty(query)) return;

        isLoading = true;
        notFound = false;
        shipment = null;
        searchedTracking = query;

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(query);
            notFound = shipment is null;
        }
        finally
        {
            isLoading = false;
        }
    }
}

