@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container py-4">
    <div class="d-flex justify-content-between align-items-center mb-4">
        <h2>📋 Dispatcher Dashboard</h2>
        <button class="btn btn-outline-primary btn-sm" @onclick="LoadShipments" disabled="@isLoading">
            @if (isLoading)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Refresh
        </button>
    </div>

    <div class="row mb-3">
        <div class="col-md-4">
            <input type="text" class="form-control" placeholder="Filter by tracking #, destination, or recipient…"
                   @bind="filterText" @bind:event="oninput" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="statusFilter">
                <option value="">All Statuses</option>
                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@s">@s</option>
                }
            </select>
        </div>
    </div>

    @if (shipments is null)
    {
        <p class="text-muted">Loading shipments…</p>
    }
    else if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments match your filters.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover align-middle">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Destination</th>
                        <th>Recipient</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td><code>@s.TrackingNumber</code></td>
                            <td>@s.Destination</td>
                            <td>@s.RecipientName</td>
                            <td><ShipmentStatusBadge Status="s.Status" /></td>
                            <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                            <td>
                                @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                                {
                                    <div class="dropdown">
                                        <button class="btn btn-sm btn-outline-secondary dropdown-toggle"
                                                type="button" @onclick="() => ToggleDropdown(s.Id)">
                                            Update
                                        </button>
                                        @if (openDropdownId == s.Id)
                                        {
                                            <div class="dropdown-menu show">
                                                @foreach (var next in GetNextStatuses(s.Status))
                                                {
                                                    <button class="dropdown-item"
                                                            @onclick="() => UpdateStatus(s.Id, next)">
                                                        @next
                                                    </button>
                                                }
                                            </div>
                                        }
                                    </div>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;
    private bool isLoading;
    private int? openDropdownId;

    private IEnumerable<ShipmentDto> FilteredShipments
    {
        get
        {
            if (shipments is null) return [];

            var result = shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(filterText))
            {
                var term = filterText.Trim();
                result = result.Where(s =>
                    s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase));
            }

            if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var st))
            {
                result = result.Where(s => s.Status == st);
            }

            return result;
        }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleDropdown(int id)
    {
        openDropdownId = openDropdownId == id ? null : id;
    }

    private static ShipmentStatus[] GetNextStatuses(ShipmentStatus current) => current switch
    {
        ShipmentStatus.Pending => [ShipmentStatus.PickedUp, ShipmentStatus.Cancelled],
        ShipmentStatus.PickedUp => [ShipmentStatus.InTransit, ShipmentStatus.Cancelled],
        ShipmentStatus.InTransit => [ShipmentStatus.OutForDelivery, ShipmentStatus.Cancelled],
        ShipmentStatus.OutForDelivery => [ShipmentStatus.Delivered, ShipmentStatus.Cancelled],
        _ => []
    };

    private async Task UpdateStatus(int id, ShipmentStatus newStatus)
    {
        openDropdownId = null;
        var updated = await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
        var existing = shipments?.FirstOrDefault(s => s.Id == id);
        if (existing is not null && shipments is not null)
        {
            var idx = shipments.IndexOf(existing);
            shipments[idx] = updated;
        }
    }
}

